import sys, json
text = sys.stdin.read()
# Try to find the JSON portion
start = text.find('{')
if start >= 0:
    data = json.loads(text[start:])
    # Pretty print all keys
    def show(d, prefix=''):
        for k, v in d.items():
            key = f'{prefix}.{k}' if prefix else k
            if isinstance(v, dict):
                show(v, key)
            else:
                print(f'{key} = {v}')
    show(data)
" 2>&1","timeout":10}

